import{_ as i,C as n,o as s,c as o,j as t,a as r,E as d,a3 as l}from"./chunks/framework.DEy3KOfk.js";const _=JSON.parse('{"title":"DynamicLightsPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/dynamic-lights-pumpkin/docs/index.md"},"headers":[],"relativePath":"packages/dynamic-lights-pumpkin/docs/index.md","filePath":"packages/dynamic-lights-pumpkin/docs/index.md","lastUpdated":1791428389000}'),p={name:"packages/dynamic-lights-pumpkin/docs/index.md"},c={id:"dynamiclightspumpkin",tabindex:"-1",class:"component-page-title"},h={class:"component-page-title__version",href:"https://github.com/filiphsps/pumpkin-plugins/releases/tag/dynamic-lights-pumpkin-v0.0.7","aria-label":"Release v0.0.7"};function m(g,e,u,y,k,f){const a=n("Badge");return s(),o("div",null,[t("h1",c,[e[0]||(e[0]=t("img",{class:"component-page-title__icon",src:"/pumpkin-plugins/packages/dynamic-lights-pumpkin/icon.svg",alt:"","aria-hidden":"true",width:"48",height:"48"},null,-1)),e[1]||(e[1]=t("span",{class:"component-page-title__text"},[r("DynamicLightsPumpkin "),t("a",{class:"header-anchor",href:"#dynamiclightspumpkin","aria-label":'Permalink to "DynamicLightsPumpkin"'},"​")],-1)),t("a",h,[d(a,{type:"info",text:"v0.0.7"})])]),e[2]||(e[2]=l('<p>DynamicLightsPumpkin shows temporary, client-only light around supported held items, dropped items, and configured entity types. The server world is not changed, so temporary light cannot replace a real block or remain after a crash.</p><p>Install <code>dynamic-lights-pumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart. On first load, grant its data-folder permissions in the server console. Players can run <code>/dynamiclights</code> to toggle the effect for themselves; the choice is remembered.</p><h2 id="light-sources" tabindex="-1">Light sources <a class="header-anchor" href="#light-sources" aria-label="Permalink to &quot;Light sources&quot;">​</a></h2><p>Built-in item sources are listed in the generated <code>config.toml</code>. Remove an item entry to disable it, set <code>light_level</code> to <code>0</code>, or add another item ID with a level from <code>0</code> to <code>15</code>. Either hand can provide light; if both do, the brighter source wins.</p><p>Entity lighting is enabled by default. The plugin checks configured entities in a 15-block cube around each player every 10 ticks by default, and sends changes when a source moves, changes level, or leaves range. Dropped items use their held-item level when the plugin observes their spawn or a player drop. Ambiguous drops and items already on the ground when the plugin starts are not guessed.</p><h2 id="updates-and-recovery" tabindex="-1">Updates and recovery <a class="header-anchor" href="#updates-and-recovery" aria-label="Permalink to &quot;Updates and recovery&quot;">​</a></h2><p>Movement within a block is ignored. Item, inventory, teleport, respawn, world-change, and entity events are applied using the completed state on the next tick. Disabling the effect or unloading the plugin restores real blocks. The plugin retains a reader for recovery data from an earlier version so it can repair temporary light levels written by that version.</p><p>See the configuration page for the item and entity tables and an example override.</p>',8))])}const b=i(p,[["render",m]]);export{_ as __pageData,b as default};
